root=pathlib.Path(__file__).resolve().parents[2]
source_rows=json.loads((root/'scripts/content/caps-sources.json').read_text())
source_by={}
for row in source_rows:source_by.setdefault(row['name'],row['url'])
source_names={'enhl':'English','afhl':'Afrikaans','xhhl':'IsiXhosa','zuhl':'IsiZulu'}
for p in P:
 p['sourceUrl']=source_by.get(source_names.get(p['code'],p['subject']),'https://www.education.gov.za/Curriculum/NCSGradesR12/CAPSFET/tabid/570/Default.aspx')
 p['sourceLabel']='DBE CAPS, Grades 10–12: '+source_names.get(p['code'],p['subject'])
 p['pdfUrl']=f"/study-packs/smartbridge-{p['id']}.pdf"
 p['minutes']=30
 if p['id']=='lisc-10':p['furtherReading']='Siyavula Grade 10 Life Sciences Learner Book, chapter 3: cell structures (indexed PDF pages 79–81). Available in the signed-in resource search. Original publisher attribution retained.'
 if p['id']=='phsc-10':p['furtherReading']='Siyavula Grade 10 Physical Sciences Learner Book, chapter 21: speed and velocity (indexed PDF page 412; printed page 396). Available in the signed-in resource search. Original publisher attribution retained.'
assert len(P)==45 and len({p['id'] for p in P})==45
(root/'src/data/study-packs.json').write_text(json.dumps(P,ensure_ascii=False,indent=2)+'\n')
print(f'Authored {len(P)} topic packs, {sum(len(p["questions"]) for p in P)} practice questions')
